"use client";

import { addCollection, Icon as IconifyIcon } from "@iconify/react/offline";
import type { IconifyJSON } from "@iconify/react/offline";
import subset from "@/components/icon-subset.json";
import type { IconName } from "@/components/icon-names";

// The offline build of @iconify/react has no API/network code path at all, so icons can only ever
// come from the bundle below - the browser never calls Iconify. The subset is generated by
// scripts/build-icon-subset.mjs; add a name there and run `npm run icons:build`.
addCollection(subset as unknown as IconifyJSON);

export type { IconName };

export type IconSize = "sm" | "md" | "lg";

interface IconProps {
  name: IconName;
  size?: IconSize;
  /**
   * Accessible name. Omit it for decorative icons sitting next to real text, which is the usual
   * case here - the icon is then hidden from assistive technology instead of repeating the label.
   */
  title?: string;
  className?: string;
  /** Draws the shape filled rather than stroked; used for the "favourited" star. */
  filled?: boolean;
}

/**
 * The one way Kobi renders an icon. Sizing comes from the --icon-* tokens in globals.css via the
 * size class rather than from inline pixel values, and colour always comes from `currentColor`,
 * so every existing dark-mode rule keeps working without an icon-specific override.
 */
export function Icon({ name, size = "md", title, className, filled = false }: IconProps) {
  const classes = ["icon", `icon-${size}`];
  if (filled) classes.push("icon-filled");
  if (className) classes.push(className);

  return (
    <IconifyIcon
      // addCollection() registers the subset under its own prefix, so the lookup has to be the
      // fully qualified Iconify name. Without the prefix the component silently renders an
      // empty <span> rather than failing.
      icon={`lucide:${name}`}
      className={classes.join(" ")}
      // Presentation attributes lose to the CSS in .icon-*, which is what sizes the icon.
      width="1em"
      height="1em"
      focusable="false"
      {...(title
        ? { role: "img", "aria-label": title }
        : { "aria-hidden": true })}
    />
  );
}
